<?php

defined('ABSPATH') || exit;

final class PLDR_Future_Insights {
    public static function event(int $edition_id,string $type,int $page,int $duration,array $context=array()) { global $wpdb;$uid=get_current_user_id();if(!$uid)return PLDR_Core::machine_error('pldr_insight_login','Log in to synchronize private reading insights.',401);$edition=PLDR_Future_Data::require_edition($edition_id);if(is_wp_error($edition))return $edition;$type=sanitize_key($type);if(!in_array($type,array('open','heartbeat','page','close'),true))return PLDR_Core::machine_error('pldr_insight_type','Unsupported reading event.',400);$duration=max(0,min(900,$duration));$wpdb->insert(PLDR_Core::table('reading_events'),array('event_id'=>PLDR_Core::uuid(),'user_id'=>$uid,'edition_id'=>$edition_id,'event_type'=>$type,'page_number'=>max(1,$page),'duration_seconds'=>$duration,'context_json'=>wp_json_encode(array('layout'=>sanitize_key((string)($context['layout']??'')),'device'=>sanitize_text_field((string)($context['device']??'')))),'created_at'=>PLDR_Core::now()));return array('stored'=>true,'private'=>true,'non_gamified'=>true); }
    public static function report(int $days=30):array { global $wpdb;$uid=get_current_user_id();if(!$uid)return array();$days=max(1,min(365,$days));$since=gmdate('Y-m-d H:i:s',time()-$days*DAY_IN_SECONDS);$seconds=(int)$wpdb->get_var($wpdb->prepare('SELECT COALESCE(SUM(duration_seconds),0) FROM '.PLDR_Core::table('reading_events').' WHERE user_id=%d AND created_at>=%s',$uid,$since));$editions=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(DISTINCT edition_id) FROM '.PLDR_Core::table('reading_events').' WHERE user_id=%d AND created_at>=%s',$uid,$since));$pages=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(DISTINCT CONCAT(edition_id,\':\',page_number)) FROM '.PLDR_Core::table('reading_events').' WHERE user_id=%d AND created_at>=%s',$uid,$since));$completed=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.PLDR_Core::table('reading_state').' WHERE user_id=%d AND percent>=%f',$uid,99.5));$recent=$wpdb->get_results($wpdb->prepare('SELECT e.edition_id,SUM(e.duration_seconds) seconds,d.title FROM '.PLDR_Core::table('reading_events').' e JOIN '.PLDR_Core::table('editions').' ed ON ed.id=e.edition_id JOIN '.PLDR_Core::table('documents').' d ON d.id=ed.document_id WHERE e.user_id=%d AND e.created_at>=%s GROUP BY e.edition_id,d.title ORDER BY seconds DESC LIMIT 10',$uid,$since),ARRAY_A)?:array();return array('days'=>$days,'reading_seconds'=>$seconds,'documents'=>$editions,'distinct_pages'=>$pages,'completed_documents'=>$completed,'most_used'=>$recent,'private'=>true,'streaks'=>false,'leaderboards'=>false,'shame_mechanics'=>false); }
}
